<script setup>
import { computed } from 'vue'
const props=defineProps({results:Array,loading:Boolean,error:String,query:String}); defineEmits(['retry'])
const searchUrl=computed(() => `https://www.zhihu.com/search?type=content&q=${encodeURIComponent(props.query || '')}`)
</script>
<template><div class="zhihu-panel"><div v-if="loading" class="skeleton" role="status"><span class="spinner"/> 正在检索知乎…<i/><i/></div><div v-else-if="error" class="error-state" role="status"><h4>暂时未能取得讨论内容</h4><p>{{ error }}</p><p>你仍可在知乎搜索相关内容。</p><button @click="$emit('retry')">重试</button></div><template v-else><article v-for="item in results" :key="item.id" class="zhihu-card"><h3><a v-if="item.url" :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }} ↗</a><template v-else>{{ item.title }}</template></h3><p>{{ item.excerpt }}</p><small>{{ item.stats }}</small><footer><a v-if="item.authorUrl" :href="item.authorUrl" target="_blank" rel="noopener noreferrer">{{ item.author }}</a><span v-else>{{ item.author }}</span></footer></article><p v-if="!results?.length" class="empty">当前分类暂无结果，可以切换分类或在知乎继续搜索。</p></template><a class="external-search" :href="searchUrl" target="_blank" rel="noopener noreferrer">在知乎搜索“{{ query?.slice(0,22) }}{{ query?.length>22?'…':'' }}” ↗</a></div></template>
